"use client";

import React from "react";
import Link from "next/link";
import * as LucideIcons from "lucide-react";
import { useBarber } from "@/context/BarberContext";

// Safe icon renderer for stability
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '24px', height: '24px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminDashboard() {
    const { appointments, barbers, services } = useBarber();

    // Calculate real stats
    const todayStr = new Date().toISOString().split('T')[0];
    const todaysApps = appointments.filter(a => a.date === todayStr);
    const completedApps = appointments.filter(a => a.status === 'concluido');
    const totalRevenue = completedApps.reduce((acc, curr) => acc + curr.price, 0);

    const stats = [
        { icon: "Users", label: "Total Clientes", value: "1.247", change: "+12%", color: "text-emerald-500" },
        { icon: "Calendar", label: "Agendamentos Hoje", value: todaysApps.length.toString(), change: "", color: "" },
        { icon: "DollarSign", label: "Faturamento Total", value: `R$ ${totalRevenue.toLocaleString()}`, change: "+18%", color: "text-emerald-500" },
        { icon: "Scissors", label: "Barbeiros Ativos", value: barbers.length.toString(), change: "", color: "" },
        { icon: "Star", label: "Serviços", value: services.length.toString(), change: "", color: "" },
    ];

    const quickActions = [
        { icon: "UserPlus", label: "Equipe", href: "/admin/profissionais" },
        { icon: "Calendar", label: "Agendamentos", href: "/admin/agendamentos" },
        { icon: "Scissors", label: "Serviços", href: "/admin/servicos" },
        { icon: "Clock", label: "Horários", href: "/admin/horarios" },
        { icon: "Wallet", label: "Financeiro", href: "/admin/financeiro" },
        { icon: "Package", label: "Estoque", href: "/admin/estoque" },
        { icon: "Megaphone", label: "Marketing", href: "/admin/marketing" },
        { icon: "Settings", label: "Configurações", href: "/admin/configuracoes" },
    ];

    return (
        <div className="p-6 lg:p-12 animate-fade-in-up">
            <header className="mb-10 lg:mb-12 flex justify-between items-end">
                <div>
                    <h1 className="text-4xl font-semibold mb-2">
                        Olá, <span className="text-[#D4AF37] italic uppercase tracking-tighter">Marciel</span>
                    </h1>
                    <p className="text-gray-400 text-sm tracking-wide">Visão geral do seu negócio em tempo real</p>
                </div>
                <div className="hidden lg:flex items-center gap-4 bg-[#111111] p-3 rounded-xl border border-[#1f1f1f]">
                    <div className="text-right">
                        <p className="text-xs font-bold text-white uppercase tracking-widest">Admin Mode</p>
                        <p className="text-[10px] text-[#D4AF37] uppercase tracking-tighter">Sincronizado</p>
                    </div>
                </div>
            </header>

            {/* Stats Cards Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4 mb-14">
                {stats.map((stat, i) => (
                    <div key={i} className="bg-[#111111] border border-[#1f1f1f] p-6 rounded-xl hover:border-[#D4AF37]/20 transition-all group relative overflow-hidden">
                        <div className="absolute top-2 right-4 text-[10px] font-bold text-emerald-500 flex items-center gap-0.5">
                            {stat.change && <><Icon name="TrendingUp" className="w-3 h-3" /> {stat.change}</>}
                        </div>
                        <div className="text-[#D4AF37] mb-4 bg-[#D4AF37]/5 w-10 h-10 rounded-lg flex items-center justify-center group-hover:bg-[#D4AF37]/10 transition-colors">
                            <Icon name={stat.icon} className="w-5 h-5" />
                        </div>
                        <h3 className="text-2xl font-bold mb-1">{stat.value}</h3>
                        <p className="text-gray-500 text-[11px] uppercase tracking-widest font-medium">{stat.label}</p>
                    </div>
                ))}
            </div>

            {/* Quick Actions Grid */}
            <section className="mb-14">
                <h2 className="text-xl font-semibold mb-6 tracking-tight">Ações Rápidas</h2>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    {quickActions.map((action, i) => (
                        <Link key={i} href={action.href} className="bg-[#111111] border border-[#1f1f1f] p-8 rounded-xl hover:border-[#D4AF37]/30 transition-all group flex flex-col items-center justify-center gap-4 active:scale-95">
                            <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-[#D4AF37] to-[#b5952f] flex items-center justify-center text-black shadow-[0_0_15px_rgba(212,175,55,0.2)] group-hover:shadow-[0_0_25px_rgba(212,175,55,0.4)] transition-all">
                                <Icon name={action.icon} className="w-6 h-6" />
                            </div>
                            <span className="text-gray-400 text-xs font-medium group-hover:text-white transition-colors tracking-wide">
                                {action.label}
                            </span>
                        </Link>
                    ))}
                </div>
            </section>

            {/* Today's Appointments Section */}
            <section className="animate-fade-in-up" style={{ animationDelay: '0.2s' }}>
                <div className="flex items-center justify-between mb-8">
                    <h2 className="text-xl font-semibold tracking-tight">Agendamentos Recentes</h2>
                    <Link href="/admin/agendamentos" className="text-[10px] uppercase font-bold text-[#D4AF37] hover:tracking-widest transition-all">Ver todos</Link>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {appointments.slice(0, 6).map((apt, i) => (
                        <div key={i} className="bg-[#111111] border border-[#1f1f1f] p-5 rounded-xl hover:border-[#D4AF37]/10 transition-all flex items-center justify-between group">
                            <div className="flex items-center gap-4">
                                <div className="text-[#D4AF37] font-black text-xs bg-[#D4AF37]/5 px-3 py-1 rounded-lg">
                                    {apt.time}
                                </div>
                                <div>
                                    <h4 className="font-bold text-sm group-hover:text-[#D4AF37] transition-colors capitalize">{apt.clientName}</h4>
                                    <p className="text-[9px] text-gray-500 uppercase tracking-tighter">{apt.serviceName} • {apt.barberName}</p>
                                    <span className={`text-[8px] font-bold uppercase tracking-widest px-1.5 py-0.5 rounded border mt-1 inline-block ${apt.status === 'concluido' ? 'text-emerald-500 border-emerald-500/20 bg-emerald-500/5' :
                                            apt.status === 'agendado' ? 'text-amber-500 border-amber-500/20 bg-amber-500/5' :
                                                'text-gray-500 border-white/5 bg-white/5'
                                        }`}>
                                        {apt.status}
                                    </span>
                                </div>
                            </div>
                        </div>
                    ))}
                    {appointments.length === 0 && (
                        <p className="text-gray-500 text-sm italic col-span-3 text-center py-10">Nenhum agendamento registrado ainda.</p>
                    )}
                </div>
            </section>

            <footer className="mt-20 border-t border-[#1a1a1a] pt-8 flex justify-between items-center opacity-40">
                <p className="text-[10px] uppercase tracking-[0.5em] text-gray-500">Master Admin Dashboard v2.0</p>
                <div className="flex gap-4">
                    <div className="w-2 h-2 rounded-full bg-emerald-500" />
                    <span className="text-[9px] uppercase tracking-widest">Sistema Ativo</span>
                </div>
            </footer>
        </div>
    );
}
